-- ============================================================
-- SEED EXT 2: Módulo 11 — Relative Clauses (exercícios 71-185)
-- Novos tópicos: reduced relative clauses, whom, preposition +
-- relative pronoun (in which/for whom), relative clauses em
-- textos acadêmicos, TOEFL Reading/Writing/Speaking
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'relative-clauses';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo relative-clauses não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 11: reduced relative clauses — present participle (-ing)
  (cid,11,71,'gap_fill','The student ___ (sit) at the back of the room raised an interesting question. (reduce the relative clause)','sitting',NULL,'Reduced relative: "who is sitting" → "sitting" (active, present participle).','medium'),
  (cid,11,72,'multiple_choice','Which is the reduced form of "researchers who are working on the project"?','researchers working on the project','["researchers worked on the project","researchers who working on the project","researchers working on the project","researchers to work on the project"]','Active reduced relative: remove "who are" → leave only -ing participle.','medium'),
  (cid,11,73,'gap_fill','Data ___ (come) from unreliable sources should not be included in the analysis.','coming',NULL,'Reduced relative: "data that comes/which comes from" → "data coming from."','medium'),
  (cid,11,74,'multiple_choice','Reduce: "The professor who teaches this module has published extensively."','The professor teaching this module has published extensively.','["The professor taught this module has published extensively.","The professor teaching this module has published extensively.","The professor to teach this module has published extensively.","The professor been teaching this module has published extensively."]','Present participle reduction: who teaches → teaching.','medium'),
  (cid,11,75,'gap_fill','Animals ___ (live) in polar regions face increasing threats from climate change.','living',NULL,'"Animals living in polar regions" = reduced from "animals that live in."','easy'),
  (cid,11,76,'multiple_choice','Which reduced relative clause is INCORRECT?','The report writing by the committee was well-received.','["The article presenting new findings was widely cited.","The student sitting next to me is from Brazil.","The report writing by the committee was well-received.","The team working on the project met yesterday."]','"Writing" is wrong for passive — should be "written." The report was WRITTEN (by the committee).','hard'),
  (cid,11,77,'gap_fill','Scientists ___ (study) climate patterns have detected an acceleration in ice melt rates.','studying',NULL,'"Scientists studying" = reduced from "scientists who study/are studying."','easy'),

  -- BLOCK 12: reduced relative clauses — past participle (passive)
  (cid,12,78,'gap_fill','The vaccine ___ (develop) by the research team has now entered clinical trials.','developed',NULL,'Passive reduced relative: "which was developed" → "developed."','medium'),
  (cid,12,79,'multiple_choice','Which is the correct reduced form of "a theory that was proposed by Einstein"?','a theory proposed by Einstein','["a theory proposing by Einstein","a theory by Einstein proposing","a theory proposed by Einstein","a theory being proposed by Einstein"]','Passive reduced relative: past participle (proposed) replaces "that was proposed."','medium'),
  (cid,12,80,'gap_fill','Results ___ (obtain) through non-peer-reviewed methods should be treated with caution.','obtained',NULL,'"Results obtained" = reduced from "results that were obtained."','medium'),
  (cid,12,81,'multiple_choice','Reduce: "The data that was collected over five years supports the hypothesis."','The data collected over five years supports the hypothesis.','["The data collecting over five years supports the hypothesis (active — wrong: data can''t collect itself).","The data that collected over five years supports the hypothesis.","The data collected over five years supports the hypothesis.","The data has collected over five years supports the hypothesis."]','"Data collected" = passive reduced relative (it was collected by someone).','medium'),
  (cid,12,82,'gap_fill','Participants ___ (select/passive) for the study must meet specific health criteria.','selected',NULL,'"Participants selected" = "participants who were selected" → passive reduced relative.','medium'),
  (cid,12,83,'multiple_choice','What is the full form of "an article written by a non-specialist"?','an article that was written by a non-specialist','["an article writing a non-specialist","an article that writes by a non-specialist","an article that was written by a non-specialist","an article which is written by a non-specialist (also correct)"]','Past participle "written" = passive relative clause: that was written.','medium'),
  (cid,12,84,'gap_fill','Evidence ___ (gather) from multiple independent sources is far more reliable.','gathered',NULL,'"Evidence gathered from" = "evidence that was gathered from" → passive reduction.','medium'),

  -- BLOCK 13: whom (formal object pronoun)
  (cid,13,85,'gap_fill','The professor ___ I most admire retired last year. (formal object relative pronoun)','whom',NULL,'"Whom" = formal object pronoun in relative clauses (I admire HIM → him → whom).','hard'),
  (cid,13,86,'multiple_choice','Which sentence uses "whom" correctly?','The researcher whom the committee selected was highly qualified.','["The researcher who the committee selected was highly qualified (who used as object — informal).","The researcher whom the committee selected was highly qualified.","The researcher which the committee selected was highly qualified.","The researcher that the committee selected was highly qualified (also correct — informal)."]','"Whom" = formal object pronoun. The committee selected HIM/HER → whom.','hard'),
  (cid,13,87,'gap_fill','The colleague with ___ I wrote the paper has just been promoted.','whom',NULL,'"With whom" = preposition + whom (formal). Never "with who."','hard'),
  (cid,13,88,'multiple_choice','How do you determine whether to use "who" or "whom"?','Replace with he/she (subject = who) or him/her (object = whom).','["Who is always formal; whom is always informal","Whom is used for things; who is for people","Replace with he/she (subject = who) or him/her (object = whom).","Who comes before verbs; whom comes after verbs only"]','Test: if you can substitute "him/her" → whom; "he/she" → who.','hard'),
  (cid,13,89,'gap_fill','The candidates ___ were shortlisted will be notified by email. (subject)','who',NULL,'"They were shortlisted" → subject → who. (Not whom — they shortlisted them → object → whom.)','medium'),
  (cid,13,90,'gap_fill','The candidates ___ the panel interviewed showed exceptional communication skills. (object)','whom / who (informal)',NULL,'The panel interviewed THEM → object → formal: whom; informal: who/that.','hard'),
  (cid,13,91,'multiple_choice','In formal academic writing, which is preferred?','Participants whom the researchers recruited were randomly assigned to two groups.','["Participants who the researchers recruited were randomly assigned.","Participants that the researchers recruited were randomly assigned.","Participants whom the researchers recruited were randomly assigned to two groups.","Participants the researchers recruited were randomly assigned. (relative pronoun omitted — also correct)"]','Formal: whom as object relative pronoun in academic writing.','hard'),

  -- BLOCK 14: preposition + relative pronoun (in which / for whom / by which / at which)
  (cid,14,92,'gap_fill','The framework ___ ___ (in which) the data was analyzed needs to be clearly described.','in which',NULL,'"In which" = formal preposition + relative pronoun for things.','hard'),
  (cid,14,93,'multiple_choice','Which is the formal academic version of "the country that she was born in"?','the country in which she was born','["the country which she was born in","the country in which she was born","the country she was born in (also correct — informal)","the country in which she was been born"]','Formal: preposition moved to front + "which": "in which."','hard'),
  (cid,14,94,'gap_fill','The mechanism ___ ___ (by which) the drug reduces inflammation is not yet fully understood.','by which',NULL,'"By which" = formal prepositional relative clause for explaining how/through what means.','hard'),
  (cid,14,95,'multiple_choice','Which sentence uses a prepositional relative clause correctly?','The conference at which the findings were presented attracted over 2,000 delegates.','["The conference which the findings were presented at attracted delegates.","The conference at which the findings were presented attracted over 2,000 delegates.","The conference in which the findings were presented attracted delegates.","The conference that the findings were presented at attracted delegates (informal — also correct)."]','"At which" for a location event (conference at which = where).','hard'),
  (cid,14,96,'gap_fill','The criteria ___ ___ (by which) applicants are assessed include academic performance and research experience.','by which',NULL,'"By which" for standard, method, or basis of evaluation.','hard'),
  (cid,14,97,'multiple_choice','Replace "the committee that we work for" with a formal relative clause:','the committee for which we work','["the committee which we work for (informal — ending a clause with a preposition)","the committee that we work for (informal)","the committee for which we work","the committee for whom we work (whom for people — committee = group, so which is preferred)"]','"For which" = preposition + which for organizations/things.','hard'),
  (cid,14,98,'gap_fill','The moment ___ ___ (at which) the theory was confirmed marked a turning point in the field.','at which',NULL,'"At which" = formal version of "when" in a relative clause about a point in time.','hard'),
  (cid,14,99,'multiple_choice','Which phrase is equivalent to "a case in which the evidence is ambiguous"?','a case where the evidence is ambiguous','["a case which the evidence is ambiguous","a case that the evidence is ambiguous","a case where the evidence is ambiguous","a case who the evidence is ambiguous"]','"In which" = "where" in relative clauses referring to situations/contexts.','medium'),

  -- BLOCK 15: relative clauses in academic writing
  (cid,15,100,'multiple_choice','[Academic] Which sentence uses a relative clause most effectively to add information?','The double-blind method, which eliminates observer bias, is the gold standard in clinical research.','["The double-blind method eliminates observer bias which is the gold standard.","The double-blind method, which eliminates observer bias, is the gold standard in clinical research.","The double-blind method which eliminates observer bias is the gold standard.","The double-blind method that eliminates observer bias is the gold standard."]','Non-defining relative clause (with commas) = adds important but non-essential information about the method.','hard'),
  (cid,15,101,'gap_fill','The phenomenon ___ the researchers observed defied all existing theoretical models.','which / that',NULL,'Defining relative clause for a thing (phenomenon) — which or that.','easy'),
  (cid,15,102,'multiple_choice','In academic writing, which relative clause structure is most formal?','a process by which nutrients are absorbed','["a process where nutrients are absorbed","a process in that nutrients are absorbed","a process by which nutrients are absorbed","a process which nutrients are absorbed by"]','Prepositional relative clause (by which) is most formal.','hard'),
  (cid,15,103,'gap_fill','Recent studies, ___ have been widely cited, suggest a link between air quality and cognitive decline.','which',NULL,'Non-defining relative clause for studies (thing) — which + commas.','medium'),
  (cid,15,104,'multiple_choice','Why do academic writers prefer "in which" over "where"?','In which is more formal and unambiguous in written academic texts.','["Where is more specific","In which is shorter","In which is more formal and unambiguous in written academic texts.","They are always interchangeable"]','Academic register preference: "in which" > "where" in formal writing.','hard'),
  (cid,15,105,'gap_fill','The rate ___ ___ (at which) deforestation is occurring has doubled in the past decade.','at which',NULL,'"At which" for rate (speed/frequency).','hard'),
  (cid,15,106,'multiple_choice','Which academic sentence INCORRECTLY uses a relative clause?','The process that was adopted, which simplified data collection, increased accuracy.','["The method, which was developed in 2015, has since been revised.","Participants who refused to complete the survey were excluded from the analysis.","The results, which were unexpected, prompted a re-evaluation of the methodology.","The process that was adopted, which simplified data collection, increased accuracy."]','Cannot use both "that" and a non-defining "which" clause for the same noun without restructuring.','hard'),

  -- BLOCK 16: TOEFL Reading
  (cid,16,107,'multiple_choice','[TOEFL Reading] "The Coriolis effect, which causes moving air and water to curve, plays a key role in large-scale atmospheric circulation." The relative clause here:','Provides additional explanatory information about the Coriolis effect.','["Identifies which Coriolis effect is being discussed (defining)","Provides additional explanatory information about the Coriolis effect.","Restricts the meaning of the noun","Is a reduced relative clause"]','Non-defining relative clause (commas) = adds non-essential but useful information.','medium'),
  (cid,16,108,'gap_fill','[TOEFL Reading] "The mechanism ___ ___ new species emerge from common ancestors is called speciation." Best relative phrase?','by which',NULL,'"By which" for the mechanism (the process/method by which something happens).','hard'),
  (cid,16,109,'multiple_choice','[TOEFL Reading] "The study draws on data collected from participants living in urban environments." The phrase "living in urban environments" is:','A reduced relative clause (who were living / who live in urban environments).','["A defining relative clause with that","A main clause adjective","A reduced relative clause (who were living / who live in urban environments).","A non-defining relative clause"]','"Living in urban environments" = present participle reduced relative clause.','hard'),
  (cid,16,110,'gap_fill','[TOEFL Reading] "The era ___ these discoveries were made saw an unprecedented expansion of scientific knowledge." Best option?','in which',NULL,'"In which these discoveries were made" = formal relative for a time period.','hard'),
  (cid,16,111,'multiple_choice','[TOEFL Reading] A passage contains: "The researchers, whose findings contradicted earlier studies, were initially met with skepticism." This tells us:','The findings — not any random researcher''s — belonged to these specific researchers.','["The researchers found something correct","The researchers plagiarized earlier studies","The findings — not any random researcher''s — belonged to these specific researchers.","The researchers agreed with earlier studies"]','"Whose" = possessive relative pronoun. The findings belonged to these researchers.','medium'),

  -- BLOCK 17: TOEFL Listening
  (cid,17,112,'multiple_choice','[TOEFL Listening] A professor says: "The concept I''m talking about, which was developed in the 1960s, has recently gained renewed attention." A student correctly identifies:','The concept = non-defining clause (extra info). Which = thing.','["A defining relative clause","Who is incorrect — should be that","The concept = non-defining clause (extra info). Which = thing.","The relative clause is wrong — should use that"]','Non-defining relative clause (with commas): which = additional information.','medium'),
  (cid,17,113,'gap_fill','[TOEFL Listening] The professor says: "The country ___ the experiment was conducted had very different healthcare systems." Best relative phrase?','in which / where',NULL,'"In which" (formal) or "where" for a country (place).','medium'),
  (cid,17,114,'multiple_choice','[TOEFL Listening] A student paraphrases: "The professor mentioned a process causing sea levels to rise." What is the full form of "causing sea levels to rise"?','which is causing sea levels to rise (or: which causes sea levels to rise)','["which cause sea levels to rise (wrong — who for things)","which is causing sea levels to rise (or: which causes sea levels to rise)","who is causing sea levels to rise","which caused sea levels to rise (wrong tense — present cause)"]','Present participle "causing" = reduced form of "which is causing / which causes."','medium'),

  -- BLOCK 18: TOEFL Speaking production
  (cid,18,115,'production','[TOEFL Speaking — 45s] Describe a person who has had a significant influence on your academic or professional life. Use at least 3 relative clauses (who, whose, whom). Include one non-defining relative clause.','',NULL,'My university professor, who taught critical thinking, changed the way I approach problems. She is someone whose teaching methods I still apply today. She was a person whom I deeply admired for her ability to make complex ideas accessible. Her course, which covered research methodology, gave me the analytical skills I needed.','hard'),
  (cid,18,116,'production','[TOEFL Speaking — 45s] Talk about a technology that has changed modern life. Use: which (non-defining), that (defining), where/in which, and one reduced relative clause (past participle).','',NULL,'The smartphone, which was invented in the early 2000s, has transformed virtually every aspect of modern life. It is a device that people use for communication, navigation, and entertainment. Apps developed for smartphones have created entire industries. A world in which everyone carries a connected computer is almost unrecognizable compared to life just thirty years ago.','hard'),

  -- BLOCK 19: TOEFL Writing production
  (cid,19,117,'production','[TOEFL Writing] Write 5 sentences about climate change research using 5 different relative clause structures: (1) who, (2) which (non-defining), (3) in which, (4) past participle reduced, (5) by which.','',NULL,'(1) Scientists who specialize in atmospheric science have documented a 1.1°C rise in global temperatures. (2) The Intergovernmental Panel on Climate Change, which was established in 1988, publishes comprehensive assessments every few years. (3) The mechanisms in which greenhouse gases trap solar radiation are now well understood. (4) Data collected over four decades confirm an accelerating warming trend. (5) The process by which CO₂ increases ocean acidity threatens marine biodiversity.','hard'),
  (cid,19,118,'production','[TOEFL Writing — Error Correction] Fix all relative clause errors: "The researcher which won the prize published a groundbreaking paper. The method that the team adopted it improved accuracy. The conference where at it was presented was in Berlin. Participants, that completed the survey, remained anonymous."','',NULL,'who won (not which for a person); the method that the team adopted (remove ''it''); the conference at which it was presented OR where it was presented; Participants who completed (not that with commas in non-defining clause).','hard'),
  (cid,19,119,'production','[TOEFL Writing — 200 words] Write an academic paragraph about the role of international collaboration in scientific research. Include: at least 5 relative clauses using different pronouns/structures (who, which [non-defining], in which, whose, reduced participle). Underline each relative clause.','',NULL,'International scientific collaboration, which has grown dramatically over the past three decades, has produced some of the most significant advances in modern research. Scientists who work across national boundaries benefit from shared resources, diverse methodologies, and complementary expertise. Projects in which multiple institutions participate often yield richer datasets and more broadly applicable findings. Researchers whose work spans disciplines — combining biology, chemistry, and data science, for example — are particularly well-positioned to address complex global challenges. The Human Genome Project, completed in 2003, exemplifies the power of a consortium built on international trust. Similarly, climate research conducted across dozens of nations has produced the unified evidence base on which global policy now rests. In environments where funding is limited, partnerships formed between universities in different countries can leverage resources that no single institution could provide alone.','hard'),

  -- BLOCK 20: advanced capstone
  (cid,20,120,'multiple_choice','[TOEFL Writing] Which sentence uses relative clauses MOST effectively for academic writing?','The phenomenon, which has been observed in multiple independent studies, suggests a mechanism by which prolonged stress alters neural connectivity in regions whose function is critical to emotional regulation.','["The phenomenon is observed in studies and suggests a mechanism and stress alters neural connectivity in regions that are critical to regulation.","The phenomenon has been observed and there is a mechanism and stress alters the neural connectivity.","The phenomenon, which has been observed in multiple independent studies, suggests a mechanism by which prolonged stress alters neural connectivity in regions whose function is critical to emotional regulation.","The phenomenon that we observe in studies suggests how stress changes the neural connectivity in regions that are very important."]','Uses: which (non-defining), by which (prepositional), whose (possessive) = sophisticated academic embedding.','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
